import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";
import * as ENV from "../config";

// -------------------------------
// 1) STUDENT — Fetch applications
// -------------------------------
export const fetchStudentApplications = createAsyncThunk(
  "applications/fetchStudentApplications",
  async (email, thunkAPI) => {
    try {
      const res = await axios.get(`${ENV.SERVER_URL}/applications/${email}`);
      return res.data;
    } catch (err) {
      return thunkAPI.rejectWithValue("Fetch failed");
    }
  }
);

// -------------------------------
// 2) STUDENT — Cancel application
// -------------------------------
export const cancelStudentApplication = createAsyncThunk(
  "applications/cancelStudentApplication",
  async (id, thunkAPI) => {
    try {
      await axios.delete(`${ENV.SERVER_URL}/applications/${id}`);
      return id;
    } catch (err) {
      return thunkAPI.rejectWithValue("Cancel failed");
    }
  }
);

// -------------------------------
// 3) COMPANY — Get job applicants
// -------------------------------
export const fetchApplicants = createAsyncThunk(
  "applications/fetchApplicants",
  async (jobId, thunkAPI) => {
    try {
      const res = await axios.get(
        `${ENV.SERVER_URL}/company/applicants/${jobId}`
      );
      return res.data;
    } catch (err) {
      return thunkAPI.rejectWithValue("Applicants fetch failed");
    }
  }
);

// -------------------------------
// 4) COMPANY — Update applicant status
// -------------------------------
export const updateApplicantStatus = createAsyncThunk(
  "applications/updateApplicantStatus",
  async ({ appId, status }, thunkAPI) => {
    try {
      const res = await axios.put(
        `${ENV.SERVER_URL}/company/applicant/${appId}`,
        { status }
      );
      return res.data;
    } catch (err) {
      return thunkAPI.rejectWithValue("Update failed");
    }
  }
);

// -------------------------------
// MAIN SLICE
// -------------------------------
const applicationSlice = createSlice({
  name: "applications",
  initialState: {
    studentApps: [],
    applicants: [],
    isLoading: false,
  },

  reducers: {},

  extraReducers: (builder) => {
    builder
      // ------------------- STUDENT -------------------
      .addCase(fetchStudentApplications.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchStudentApplications.fulfilled, (state, action) => {
        state.isLoading = false;
        state.studentApps = action.payload;
      })
      .addCase(cancelStudentApplication.fulfilled, (state, action) => {
        state.studentApps = state.studentApps.filter(
          (app) => app._id !== action.payload
        );
      })

      // ------------------- COMPANY -------------------
      .addCase(fetchApplicants.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchApplicants.fulfilled, (state, action) => {
        state.isLoading = false;
        state.applicants = action.payload;
      })
      .addCase(updateApplicantStatus.fulfilled, (state, action) => {
        const updated = action.payload;

        state.applicants = state.applicants.map((app) =>
          app._id === updated._id ? updated : app
        );
      });
  },
});

export default applicationSlice.reducer;
